 if not isinstance(template,dict):
  violations.append({'source_span':None,'raw_line':None,'parsed_value':clone(template),'id_presence':'not_an_object','reason':'template_not_object'})
 else:
  raw=template.get('raw_utf8')
  if raw is not None and not isinstance(raw,str):violations.append({'source_span':None,'raw_line':None,'parsed_value':clone(raw),'id_presence':'not_an_object','reason':'raw_not_string'})
  elif isinstance(raw,str):
   for line,text in enumerate(raw.splitlines(),1):
    span={'start_line':line,'end_line':line};reason=None;presence='not_an_object'
    try:value=json.loads(text)
    except (ValueError,TypeError):value=None;reason='line_not_json'
    if reason is None:
     if not isinstance(value,dict):reason='element_not_object'
     else:
      presence='absent' if 'id' not in value else 'explicit_null' if value['id'] is None else 'supplied'
      if 'id' not in value or value['id'] is None:reason='element_id_missing'
      elif not isinstance(value['id'],str) or value['id']=='':reason='element_id_not_nonempty_string'
    if reason is not None:violations.append({'source_span':span,'raw_line':text,'parsed_value':clone(value),'id_presence':presence,'reason':reason})
 return {'domain_valid':len(violations)==0,'violations':violations,'actual_validation_effect':False}

# Proposed finite logical definitions only. Not imported or executed in this stage.
# document_type and document_schema resolve the pinned same-document type/schema
# objects; they are pure finite-model read operators, not runtime file IO.
N01_ABSENT = object()
N01_OK = 'supported_synthetic_condition'
N01_EFFECTS = EFFECT_FIELDS


class N01PrivateContractError(Exception):
    def __init__(self, kind, arguments, domain_observations):
        self.problem = {'kind': kind, 'arguments': clone(arguments), 'domain_observations': clone(domain_observations)}
        super().__init__(kind)


def n01_member(value, name):
    return value.get(name, N01_ABSENT) if isinstance(value, dict) else N01_ABSENT


def n01_presence(value):
    return {'presence': 'absent'} if value is N01_ABSENT else {'presence': 'present', 'value': clone(value)}


def n01_state_of(actual, expected, revision=False):
    if actual is N01_ABSENT:
        return 'missing'
    return state_of(actual, None if expected is N01_ABSENT else expected, revision)


def n01_json_value(value):
    if value is None or type(value) in (bool, str, int):
        return True
    if type(value) is float:
        try:
            canonical(value)
            return True
        except ValueError:
            return False
    if isinstance(value, list):
        return all(n01_json_value(v) for v in value)
    if isinstance(value, dict):
        return all(type(k) is str and n01_json_value(v) for k, v in value.items())
    return False


def n01_type_valid(t, value):
    # Exact existing L5 grammar; normalized new logical kinds are not sent here.
    kind = t['kind']
    if kind == '論理JSON値':
        if not same(t, document_type('/types/JsonValue')):
            raise ValueError('unrecognized logical JSON alias')
        return n01_json_value(value)
    if kind == 'ref':
        return n01_type_valid(document_type('/types/' + t['target']), value)
    if kind == 'json':
        return n01_json_value(value)
    if kind == 'union':
        return any(n01_type_valid(v, value) for v in t['variants'])
    if kind in ('string', 'boolean', 'integer', 'null'):
        ok = (type(value) is str if kind == 'string' else type(value) is bool if kind == 'boolean' else type(value) is int if kind == 'integer' else value is None)
        return ok and ('domain' not in t or any(same(value, v) for v in t['domain']))
    if kind == 'list':
        return isinstance(value, list) and all(n01_type_valid(t['items'], v) for v in value)
    if kind == 'map':
        return isinstance(value, dict) and all(type(k) is str and n01_type_valid(t['values'], v) for k, v in value.items())
    if kind == 'record':
        if not isinstance(value, dict):
            return False
        fields = t['fields']
        if t.get('additional_properties') == 'closed_declared_carrier' and set(value) - set(fields):
            return False
        for name, field in fields.items():
            if name not in value:
                if 'absent' not in field['presence_states']:
                    return False
            elif value[name] is None and 'null' not in field['presence_states']:
                return False
            elif not n01_type_valid(field['type'], value[name]):
                return False
        return True
    raise ValueError('unsupported existing L5 type kind: ' + kind)


def n01_trace_packet_type():
    # A read-only view derived from the original packet type. The original public
    # type and the raw packet are not rewritten. Raw success carriers stay raw.
    t = clone(document_type('/types/N01Arguments/fields/packet/type'))
    t['additional_properties'] = 'preserve_raw_observation'
    for name in ['held_out_source_binding', 'held_out_extraction_batch']:
        t['fields'][name] = {'presence_states': ['absent', 'provided', 'null'], 'type': {'kind': 'json'}}
    t['fields']['held_out_source']['presence_states'].append('absent')
    for v in t['fields']['held_out_source']['type']['variants']:
        if v['kind'] == 'record':
            v['additional_properties'] = 'preserve_raw_observation'
            v['fields']['raw_utf8']['presence_states'].append('absent')
    # The existing applicable signature explicitly includes optional screen with
    # boolean|string|null. Success atom schema still requires boolean applicability.
    inputs = t['fields']['input_frame']['type']['fields']['applicability_input']['type']
    inputs['additional_properties'] = 'preserve_raw_observation'
    inputs['fields']['screen'] = {'presence_states': ['absent', 'provided', 'null'], 'type': {'kind': 'union', 'variants': [{'kind': 'boolean'}, {'kind': 'string'}, {'kind': 'null'}]}}
    return t


def n01_trace_packet_domain(packet):
    return n01_type_valid(n01_trace_packet_type(), packet)


def n01_raw_trace_domain(packet, retained):
    return n01_trace_packet_domain(packet) and n01_type_valid(document_type('/types/RetainedContext'), retained)


def n01_domain_observations(packet):
    observations = []
    for name in ['original_template', 'held_out_source']:
        value = n01_member(packet, name)
        # The original nullable validator can inspect the absent projection, while
        # the raw Presence remains absent in the independent saved observation.
        report = check_template_domain(None if value is N01_ABSENT else value)
        observations.append({'input_pointer': '/packet/' + name, 'input': n01_presence(value), 'returned': clone(report)})
    return observations


def n01_require_legacy_shape(packet, retained):
    # Public old2 never gains the broader private raw domain through the union
    # shared producer. Valid legacy shapes do not reparse the source here.
    if not (n01_type_valid(document_type('/types/N01Arguments/fields/packet/type'), packet) and n01_type_valid(document_type('/types/RetainedContext'), retained)):
        raise N01PrivateContractError('declared_domain_violation', {'packet': packet, 'retained': retained}, n01_domain_observations(packet))


def n01_require_shared_domain(packet, retained):
    reports = n01_domain_observations(packet)
    legacy = n01_type_valid(document_type('/types/N01Arguments/fields/packet/type'), packet) and n01_type_valid(document_type('/types/RetainedContext'), retained)
    if not (legacy or n01_raw_trace_domain(packet, retained)) or any(not v['returned']['domain_valid'] for v in reports):
        raise N01PrivateContractError('declared_domain_violation', {'packet': packet, 'retained': retained}, reports)
    return reports


def n01_require_same_values(packet, context, shared):
    # Origin is established by the private caller graph, not inferred from values.
    arguments = {'packet': packet, 'context': context, 'shared': shared}
    if not same(packet, shared['input_snapshot']):
        raise N01PrivateContractError('packet_snapshot_mismatch', arguments, [])
    if not same(context['unaffected_Q'], shared['common']['unaffected_Q']):
        raise N01PrivateContractError('retained_Q_mismatch', arguments, [])


def n01_shape_valid(name, value):
    # Exact declared subset of the pinned basic return schema. No library choice.
    root = document_schema('/n01_private_type_contract/return_schema')
    def check(s, v):
        if s is True:
            return True
        if s is False:
            return False
        if '$ref' in s:
            return check(root['$defs'][s['$ref'].split('/')[-1]], v)
        if 'oneOf' in s and sum(check(x, v) for x in s['oneOf']) != 1:
            return False
        if 'not' in s and check(s['not'], v):
            return False
        if 'const' in s and not same(v, s['const']):
            return False
        if 'enum' in s and not any(same(v, x) for x in s['enum']):
            return False
        def has_type(k):
            return (isinstance(v, dict) if k == 'object' else isinstance(v, list) if k == 'array' else type(v) is str if k == 'string' else type(v) is int if k == 'integer' else type(v) in (int, float) if k == 'number' else type(v) is bool if k == 'boolean' else v is None if k == 'null' else False)
        if 'type' in s and not any(has_type(k) for k in (s['type'] if isinstance(s['type'], list) else [s['type']])):
            return False
        if isinstance(v, dict):
            if any(k not in v for k in s.get('required', [])):
                return False
            properties = s.get('properties', {})
            if s.get('additionalProperties') is False and set(v) - set(properties):
                return False
            if any(not check(t, v[k]) for k, t in properties.items() if k in v):
                return False
        if isinstance(v, list) and 'items' in s and not all(check(s['items'], x) for x in v):
            return False
        if type(v) is str and 'pattern' in s and re.fullmatch(s['pattern'], v) is None:
            return False
        if type(v) in (int, float) and 'minimum' in s and v < s['minimum']:
            return False
        return True
    return check(root['$defs'][name], value)


def n01_source_level_missing(held):
    if not isinstance(held, dict):
        return None
    raw = n01_member(held, 'raw_utf8')
    if raw is not N01_ABSENT and raw is not None and raw != '':
        return None
    return {'element_id': None, 'kind': 'template_source_missing', 'template_revision': held['revision'], 'source_span': None}


def n01_parsed_rows(held):
    if held is N01_ABSENT or held is None:
        return []
    # The source domain was checked before shared generation. All nonempty lines
    # are original JSON objects with a nonempty id; no fallback object is made.
    return [{'element': json.loads(line), 'span': {'start_line': number, 'end_line': number}, 'ordinal': number, 'row_sha256': text_digest(line)} for number, line in enumerate(held['raw_utf8'].splitlines(), 1)]


def n01_source_diagnosis(held, frame, row):
    scope_state = n01_state_of(n01_member(held, "scope"), n01_member(frame, "scope"))
    if scope_state != N01_OK:
        return "scope_" + scope_state
    revision = n01_member(held, "revision")
    if revision is N01_ABSENT or revision is None or revision == "":
        return "source_revision_missing"
    if revision == "TBD":
        return "source_revision_unknown"
    if text_digest(held["raw_utf8"]) != held.get("sha256"):
        return "source_digest_conflict"
    if row["element"].get("kind") not in KINDS:
        return "unsupported_element"
    return None

def n01_comparison_result(packet):
    # 旧L5 definition19の独立二結果比較。held-out branchとは別計算。
    sources = packet.get("result_sources") or []
    frame = packet.get("input_frame") or {}
    template = packet.get("original_template") or {}
    if packet.get("independence_qualification") != "known_in_synthetic_fixture":
        state = "unknown"
    elif len(sources) != 2:
        state = "missing"
    elif sources[0].get("run_id") in [None, "", "TBD"] or sources[0].get("run_id") == sources[1].get("run_id"):
        state = "unknown"
    elif frame.get("template_revision") != template.get("revision"):
        state = "stale"
    elif text_digest(template.get("raw_utf8", "")) != template.get("sha256"):
        state = "conflict"
    else:
        input_digest = value_digest({"template": template, "input": frame})
        states = []
        for source in sources:
            states += [n01_state_of(source.get("input_sha256"), input_digest), n01_state_of(source.get("semantic_digest"), value_digest(source.get("content")))]
        states.append(n01_state_of(sources[0].get("semantic_digest"), sources[1].get("semantic_digest")))
        state = aggregate(states)
    return {"state": state, "value": "equal_for_this_fixture_input_only" if state == N01_OK else None}

def n01_reference_states(actual, expected):
    if actual is N01_ABSENT:
        return ["missing"]
    if not isinstance(actual, dict):
        return ["unknown"]
    states = [n01_state_of(n01_member(actual, field), n01_member(expected, field), field == "revision") for field in ["identity", "revision", "scope", "owner", "sha256"]]
    # Optional locator is preserved in each original Ref. Without an independent
    # resolver observation, its absence/difference alone produces no new state.
    return states

def n01_unresolved(request, state, source_observation, qualification_observation, basis_refs):
    return {"kind": "unresolved", "request": clone(request), "state": state, "source_observation": clone(source_observation), "qualification_observation": clone(qualification_observation), "basis_refs": clone(basis_refs)}

def resolve_n01_owner_source(request, source_return, qualifier_return):
    """原決定の適用と独立両端を計算。source取得失敗はcallerが別経路処理。"""
    source = source_return["record"]
    if qualifier_return["kind"] == "unresolved":
        return n01_unresolved(request, qualifier_return["state"], n01_presence(source), qualifier_return["observed"], qualifier_return["basis_refs"])
    qualification = qualifier_return["record"]
    decision = qualification.get("decision")
    outcome = decision.get("outcome") if isinstance(decision, dict) else None
    if outcome != "applicable":
        state = {"not_applicable": "conflict", "revoked": "stale", "indeterminate": "unknown"}.get(outcome, "unknown")
        return n01_unresolved(request, state, n01_presence(source), n01_presence(qualification), qualification["basis_refs"])
    states = n01_reference_states(source["source_ref"], request["source_ref"])
    states += n01_reference_states(qualification["subject_ref"], source["source_ref"])
    states += [n01_state_of(source["source_ref"].get("sha256"), text_digest(source["raw_utf8"])), n01_state_of(qualification.get("source_bytes_sha256"), text_digest(source["raw_utf8"])), n01_state_of(qualification.get("owner"), source["source_ref"].get("owner"))]
    state = aggregate(states)
    if state != N01_OK:
        return n01_unresolved(request, state, n01_presence(source), n01_presence(qualification), qualification["basis_refs"])
    return {"kind": "resolved", "request": clone(request), "source": {"source_ref": clone(source["source_ref"]), "raw_utf8": source["raw_utf8"]}, "qualification": {field: clone(qualification[field]) for field in ["subject_ref", "owner", "source_bytes_sha256", "basis_refs", "decision"]}, "native_source_record": clone(source), "native_qualification_record": clone(qualification)}

def n01_binding_leaf_states(binding, source, held):
    if binding is N01_ABSENT:
        return ["missing"]
    if not isinstance(binding, dict):
        return ["unknown"]
    states = n01_reference_states(n01_member(binding, "source_ref"), source["source_ref"])
    expected = {"raw_revision": held.get("revision"), "raw_scope": held.get("scope"), "raw_sha256": text_digest(source["raw_utf8"]), "raw_source_pointer": "/held_out_source/raw_utf8"}
    states += [n01_state_of(n01_member(binding, field), value, field == "raw_revision") for field, value in expected.items()]
    if set(binding) - {"source_ref", "raw_revision", "raw_scope", "raw_sha256", "raw_source_pointer"}:
        states.append("unknown")
    return states

def n01_semantic_binding(packet, context):
    binding = n01_member(packet, "held_out_source_binding")
    if binding is N01_ABSENT:
        return "missing"
    if not isinstance(binding, dict):
        return "unknown"
    resolution_presence = context["held_out_owner_resolution"]
    if resolution_presence["presence"] == "absent":
        return "missing"
    resolution = resolution_presence["value"]
    if resolution["kind"] == "unresolved":
        return resolution["state"]
    source = resolution["source"]
    held = packet["held_out_source"]
    states = n01_binding_leaf_states(binding, source, held)
    states += [n01_state_of(held["raw_utf8"], source["raw_utf8"]), n01_state_of(held.get("revision"), source["source_ref"].get("revision"), True), n01_state_of(held.get("scope"), source["source_ref"].get("scope"))]
    batch = n01_member(packet, "held_out_extraction_batch")
    if batch is not N01_ABSENT and batch is not None:
        if not isinstance(batch, dict):
            states.append('unknown')
        else:
            states += n01_binding_leaf_states(n01_member(batch, "source_binding"), source, held)
            frame = packet["input_frame"]
            contract = {"identity": frame.get("extractor_identity"), "version": frame.get("extractor_version")}
            states += [n01_state_of(n01_member(batch, "applicability_input"), frame.get("applicability_input")), n01_state_of(n01_member(batch, "extractor_contract"), contract), n01_state_of(n01_member(batch, "extractor_version_digest"), value_digest(contract))]
    return aggregate(states)

def n01_discover(batch, row_count):
    candidates = [[] for _ in range(row_count)]
    unmatched = []
    occurrences = n01_member(batch, "occurrences")
    if isinstance(occurrences, list):
        for index, value in enumerate(occurrences):
            ordinal = n01_member(value, "source_ordinal")
            if type(ordinal) is int and 1 <= ordinal <= row_count:
                candidates[ordinal - 1].append(index)
            else:
                unmatched.append(index)
    return candidates, unmatched, occurrences

def n01_rejected_atom(occurrences, indices):
    if len(indices) == 1:
        candidate = occurrences[indices[0]]
        return n01_presence(n01_member(n01_member(candidate, "outcome"), "atom"))
    return {"presence": "absent"}

def n01_gap_for(row, held, kind):
    return {"element_id": row["element"].get("id"), "kind": kind, "template_revision": held.get("revision"), "source_span": clone(row["span"])}

def n01_row_outcome(packet, row, indices, occurrences, diagnosis, binding_state):
    held = packet["held_out_source"]
    frame = packet["input_frame"]
    kind = diagnosis
    if kind is None and binding_state != N01_OK:
        kind = {"missing": "source_binding_missing", "unknown": "source_binding_unknown", "stale": "source_revision_stale", "conflict": "source_binding_conflict"}[binding_state]
    if kind is None:
        applies = applicable(row["element"], frame.get("applicability_input") or {})
        if applies != "yes":
            kind = "applicability_" + applies
    if kind is None:
        if len(indices) == 0:
            kind = "extraction_result_missing"
        elif len(indices) > 1:
            kind = "atom_source_conflict"
    if kind is None:
        candidate = occurrences[indices[0]]
        claims = {"source_ordinal": row["ordinal"], "source_element_id": row["element"].get("id"), "source_span": row["span"], "source_row_sha256": row["row_sha256"]}
        if any(n01_member(candidate, field) is N01_ABSENT or not same(candidate[field], value) for field, value in claims.items()):
            kind = "atom_source_conflict"
    atom = None
    if kind is None:
        outcome = n01_member(candidate, "outcome")
        if outcome is N01_ABSENT or outcome is None:
            kind = "extraction_result_missing"
        elif not isinstance(outcome, dict):
            kind = "extraction_result_invalid"
        elif outcome.get("kind") == "gap" and set(outcome) == {"kind", "gap"}:
            gap = outcome["gap"]
            if not n01_shape_valid('HeldOutGap', gap):
                kind = "extraction_result_invalid"
            elif gap.get("element_id") != row["element"].get("id") or not same(gap.get("source_span"), row["span"]) or gap.get("template_revision") != held.get("revision"):
                kind = "atom_source_conflict"
            else:
                kind = "producer_reported_gap"
        elif outcome.get("kind") == "atom" and set(outcome) == {"kind", "atom"}:
            atom = outcome["atom"]
            if not isinstance(atom, dict) or not isinstance(atom.get("atom_id"), str) or not isinstance(atom.get("content"), dict):
                kind = "extraction_result_invalid"
        else:
            kind = "extraction_result_invalid"
    if kind is None:
        expected = {"source_element_id": row["element"].get("id"), "source_span": row["span"], "template_revision": held.get("revision"), "applicability": frame.get("applicability_input"), "kind": row["element"].get("kind"), "meaning": row["element"].get("meaning"), "extractor_identity": frame.get("extractor_identity"), "extractor_version": frame.get("extractor_version")}
        state = aggregate([n01_state_of(n01_member(atom["content"], field), value, field in {"template_revision", "extractor_version"}) for field, value in expected.items()])
        if state != N01_OK:
            kind = {"missing": "atom_content_missing", "unknown": "atom_content_unknown", "stale": "source_revision_stale", "conflict": "atom_content_conflict"}[state]
    if kind is None:
        contract = {"identity": frame.get("extractor_identity"), "version": frame.get("extractor_version")}
        for actual, expected in [(n01_member(atom, "semantic_digest"), value_digest(atom["content"])), (n01_member(atom, "extractor_version_digest"), value_digest(contract))]:
            state = n01_state_of(actual, expected)
            if state != N01_OK:
                kind = {"missing": "atom_digest_missing", "unknown": "atom_digest_unknown", "conflict": "atom_digest_conflict"}[state]
                break
    if kind is None:
        if not n01_shape_valid('HeldOutAtomEvidence', atom):
            kind = "extraction_result_invalid"
    if kind:
        return {"kind": "gap", "gap": n01_gap_for(row, held, kind), "rejected_atom": n01_rejected_atom(occurrences, indices)}
    return {"kind": "atom", "atom": clone(atom)}

def n01_source_views(shared):
    """Rename stored observations for existing traced stages; no source parsing."""
    rows, diagnoses = [], []
    for value in shared["source"]["rows"]:
        rows.append({"element": value["source_element"], "span": value["source_span"], "ordinal": value["source_ordinal"], "row_sha256": value["source_row_sha256"]})
        finding = value["source_finding"]
        diagnoses.append(None if finding["presence"] == "absent" else finding["value"]["kind"])
    return rows, diagnoses

def evaluate_n01_shared(packet, retained):
    """Same-call producer only. Q is opaque; source diagnosis is evaluated once."""
    n01_require_shared_domain(packet, retained)
    snapshot = clone(packet)
    common = {
        "comparison_result": n01_comparison_result(snapshot),
        "general_determinism_guaranteed": False,
        "all_templates_supported": False,
        "effects": {field: False for field in N01_EFFECTS},
        "unaffected_Q": clone(retained["unaffected_Q"]),
    }
    frame = snapshot.get("input_frame") or {}
    held = n01_member(snapshot, "held_out_source")
    source_gap = n01_source_level_missing(held)
    rows = [] if source_gap is not None else n01_parsed_rows(held)
    source_rows = []
    for row in rows:
        diagnosis = n01_source_diagnosis(held, frame, row)
        source_rows.append({
            "source_ordinal": row["ordinal"],
            "source_span": clone(row["span"]),
            "source_row_sha256": row["row_sha256"],
            "source_element": clone(row["element"]),
            "source_finding": n01_presence(n01_gap_for(row, held, diagnosis)) if diagnosis is not None else n01_presence(N01_ABSENT),
        })
    return {
        "input_snapshot": snapshot,
        "common": common,
        "source": {"source_level_gap": n01_presence(source_gap) if source_gap is not None else n01_presence(N01_ABSENT), "rows": source_rows},
    }

def project_n01_legacy(shared):
    """Closed six-member view of source-only findings, without native operands."""
    source = shared["source"]
    source_gap = source["source_level_gap"]
    if source_gap["presence"] == "present":
        gap = clone(source_gap["value"])
    else:
        gaps = [clone(row["source_finding"]["value"]) for row in source["rows"] if row["source_finding"]["presence"] == "present"]
        gap = None if not gaps else gaps[0] if len(gaps) == 1 else gaps
    return {**clone(shared["common"]), "held_out_gap": gap}

def compare_n01_with_held_out_trace(packet, context, shared):
    n01_require_same_values(packet, context, shared)
    # The same caller supplies packet=shared.input_snapshot and its context.
    # Shared is a typed producer result; this is not a raw state decoder.
    rows, diagnoses = n01_source_views(shared)
    source_gap_presence = shared["source"]["source_level_gap"]
    source_gap = None if source_gap_presence["presence"] == "absent" else source_gap_presence["value"]
    batch = n01_member(packet, "held_out_extraction_batch")
    indices, unmatched, occurrences = n01_discover(batch, len(rows))
    binding = n01_member(packet, "held_out_source_binding")
    eligible = any(diagnosis is None for diagnosis in diagnoses)
    if source_gap is not None:
        typed = {"state": "not_evaluated", "preceding_source_finding_kinds": [source_gap["kind"]], "input_pointer": "/packet/held_out_source_binding"}
    elif not rows:
        typed = {"state": "not_applicable", "reason": "held_out_source has no parsed source row"}
    elif not eligible:
        typed = {"state": "not_evaluated", "preceding_source_finding_kinds": clone(diagnoses), "input_pointer": "/packet/held_out_source_binding"}
    elif binding is N01_ABSENT:
        typed = {"state": "missing", "finding_kind": "source_binding_missing", "input_pointer": "/packet/held_out_source_binding"}
    elif n01_shape_valid('N01HeldOutSourceBinding', binding):
        typed = {"state": "valid", "value": clone(binding), "input_pointer": "/packet/held_out_source_binding"}
    elif isinstance(binding, dict):
        typed = {"state": "unknown", "reason": "binding_field_not_strict", "input_pointer": "/packet/held_out_source_binding", "raw_value": n01_presence(binding)}
    else:
        typed = {"state": "unknown", "reason": "binding_outer_not_object", "input_pointer": "/packet/held_out_source_binding", "raw_value": n01_presence(binding)}
    binding_state = n01_semantic_binding(packet, context) if eligible else None
    results = []
    for row, diagnosis, candidate_indices in zip(rows, diagnoses, indices):
        result = {"observed_source_binding": n01_presence(n01_member(batch, "source_binding")), "source_element_id": row["element"].get("id"), "source_span": clone(row["span"]), "outcome": n01_row_outcome(packet, row, candidate_indices, occurrences, diagnosis, binding_state), "source_ordinal": row["ordinal"], "source_row_sha256": row["row_sha256"], "source_element": clone(row["element"]), "candidate_batch_indices": clone(candidate_indices)}
        results.append(result)
    gaps = [clone(result["outcome"]["gap"]) for result in results if result["outcome"]["kind"] == "gap"]
    gap_projection = clone(source_gap) if source_gap is not None else None if not gaps else gaps[0] if len(gaps) == 1 else gaps
    result = {**clone(shared["common"]), "held_out_gap": gap_projection, "held_out_occurrence_results": results, "held_out_batch_association": {"expected_source_binding": n01_presence(binding), "typed_expected_source_binding": typed, "batch_input": n01_presence(batch), "unmatched_batch_indices": unmatched}}
    return result

def make_n01_resolved_context(retained, owner_result):
    return {'unaffected_Q': clone(retained['unaffected_Q']), 'held_out_owner_resolution': clone(owner_result)}


def call_n01_with_held_out_trace(packet, retained, source_request, ports):
    # This caller does not accept shared/context/resolution as incoming arguments.
    shared = evaluate_n01_shared(packet, retained)
    snapshot = shared['input_snapshot']
    rows, diagnoses = n01_source_views(shared)
    request = N01_ABSENT if source_request['presence'] == 'absent' else source_request['value']
    eligible = any(d is None for d in diagnoses)
    if not rows or not eligible:
        source_call = qualification_call = {'not_called_reason': 'no_eligible_held_source'}
        resolution = N01_ABSENT
    elif request is N01_ABSENT:
        source_call = qualification_call = {'not_called_reason': 'source_request_missing'}
        resolution = N01_ABSENT
    else:
        source_return = ports['read_n01_owner_source'](clone(request))
        source_call = {'arguments': clone(request), 'returned': clone(source_return)}
        if source_return['kind'] == 'unresolved':
            qualification_call = {'not_called_reason': 'source_unresolved'}
            resolution = n01_unresolved(request, source_return['state'], source_return['observed'], {'presence': 'absent'}, source_return['basis_refs'])
        else:
            source = source_return['record']
            qualification_request = {'subject_ref': clone(source['source_ref']), 'source_record_ref': clone(source['record_ref']), 'source_bytes_sha256': text_digest(source['raw_utf8'])}
            qualification_return = ports['read_n01_owner_qualification'](clone(qualification_request))
            qualification_call = {'arguments': clone(qualification_request), 'returned': clone(qualification_return)}
            resolution = resolve_n01_owner_source(request, source_return, qualification_return)
    context = make_n01_resolved_context(retained, n01_presence(resolution))
    returned = compare_n01_with_held_out_trace(snapshot, context, shared)
    observation = {'source_call': clone(source_call), 'qualification_call': clone(qualification_call), 'resolution': n01_presence(N01_ABSENT) if resolution is N01_ABSENT else clone(resolution), 'context': clone(context), 'n01_arguments': {'packet': clone(snapshot), 'context': clone(context), 'shared': clone(shared)}}
    return {'returned': returned, 'observation': observation}

n01_caller_structure_contract.validator_source:
"""Validate the declared closed finite notation and private direct caller graph.
This source checker runs no N01 business function and observes no runtime arguments.
"""
import ast
import hashlib


def check_n01_caller_structure(definitions, entry_contract):
    nodes, problems, modules = [], [], []
    def problem(kind, owner, index, source, node=None, line=1):
        if node is not None:
            line = node.lineno
            excerpt = ast.get_source_segment(source, node) or ''
        else:
            lines = source.splitlines()
            excerpt = lines[line-1] if 0 < line <= len(lines) else ''
        problems.append({'kind': kind, 'function_symbol': owner, 'definition_index': index, 'source_line': line, 'source_excerpt': excerpt})
    for index, text in enumerate(definitions):
        try:
            tree = ast.parse(text)
        except SyntaxError as error:
            problem('outside_closed_notation', '<module>', index, text, line=error.lineno or 1)
            continue
        modules.append((index, text, tree))
        nodes.extend((index, text, node) for node in tree.body if isinstance(node, (ast.FunctionDef, ast.ClassDef)))
    seen = set()
    for index, text, node in nodes:
        if node.name in seen:
            problem('duplicate_symbol', node.name, index, text, node)
        seen.add(node.name)
    if problems:
        return {'valid': False, 'problems': problems}
    by_name = {node.name: (index, text, node) for index, text, node in nodes}
    symbol = entry_contract['caller']
    if symbol not in by_name or not isinstance(by_name[symbol][2], ast.FunctionDef):
        problem('missing_direct_call', symbol, 0, definitions[0] if definitions else '')
        return {'valid': False, 'problems': problems}
    # This notation allows direct calls to declared functions and fixed builtins,
    # declared JSON/list/string methods, and exactly the two typed native ports.
    # Callable aliases, reflection, imports and other dynamic calls are outside it.
    declared = {n.name for _, _, tree in modules for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.ClassDef))}
    builtins = {'all','any','bool','dict','enumerate','Exception','int','isinstance','len','list','next','object','range','set','str','sum','super','tuple','type','zip','ValueError','TypeError','document_type','document_schema'}
    methods = {'__init__','append','deepcopy','dumps','encode','fromkeys','get','hexdigest','items','loads','replace','search','sha256','split','splitlines','values','extend'}
    protected = {'evaluate_n01_shared', entry_contract['core'], 'make_n01_resolved_context'}
    unsupported = (ast.Lambda, ast.Import, ast.ImportFrom, ast.Await, ast.Yield, ast.YieldFrom, ast.Global, ast.Nonlocal, ast.Delete, ast.With, ast.AsyncWith, ast.AsyncFunctionDef)
    for index, text, tree in modules:
        parents = {child: parent for parent in ast.walk(tree) for child in ast.iter_child_nodes(parent)}
        for node in ast.walk(tree):
            if isinstance(node, unsupported):
                problem('outside_closed_notation', '<module>', index, text, node)
            if isinstance(node, ast.Name) and node.id in protected and isinstance(node.ctx, ast.Load):
                parent = parents.get(node)
                if not (isinstance(parent, ast.Call) and parent.func is node):
                    problem('outside_closed_notation', '<module>', index, text, node)
            if isinstance(node, ast.Name) and node.id in protected and isinstance(node.ctx, ast.Store):
                problem('outside_closed_notation', '<module>', index, text, node)
            if not isinstance(node, ast.Call):
                continue
            f = node.func
            if isinstance(f, ast.Name):
                if f.id not in declared | builtins or f.id in entry_contract['forbidden_raw_decoders']:
                    problem('raw_private_decode' if f.id in entry_contract['forbidden_raw_decoders'] else 'outside_closed_notation', '<module>', index, text, node)
            elif isinstance(f, ast.Attribute):
                if f.attr not in methods:
                    problem('outside_closed_notation', '<module>', index, text, node)
            elif not (isinstance(f, ast.Subscript) and isinstance(f.value, ast.Name) and f.value.id == 'ports' and isinstance(f.slice, ast.Constant) and f.slice.value in {'read_n01_owner_source','read_n01_owner_qualification'}):
                problem('outside_closed_notation', '<module>', index, text, node)
    index, text, caller = by_name[symbol]
    # Caller control flow is an exact declared AST skeleton. This closes order,
    # dominance and mutation scope without claiming arbitrary Python proof.
    # Line numbers/comments/formatting are irrelevant; executable structure is not.
    caller_ast = ast.dump(caller, annotate_fields=True, include_attributes=False)
    if hashlib.sha256(caller_ast.encode()).hexdigest() != entry_contract['caller_skeleton_ast_sha256']:
        problem('outside_closed_notation', symbol, index, text, caller)
    def issue(kind, node):
        problem(kind, symbol, index, text, node)
    args = [a.arg for a in caller.args.args]
    if args != entry_contract['parameters'] or caller.args.vararg or caller.args.kwarg or caller.args.kwonlyargs or any(k in args for k in ['shared','context','resolution']):
        issue('external_shared_parameter', caller)
    def assigned(name):
        return [n for n in ast.walk(caller) if isinstance(n, ast.Assign) and any(isinstance(t, ast.Name) and t.id == name for t in n.targets)]
    producers = assigned('shared')
    if len(producers) != 1:
        issue('multiple_shared_producers', caller)
    else:
        value = producers[0].value
        if not (isinstance(value, ast.Call) and isinstance(value.func, ast.Name) and value.func.id == 'evaluate_n01_shared' and len(value.args)==2 and not value.keywords and all(isinstance(v, ast.Name) and v.id == name for v,name in zip(value.args,['packet','retained']))):
            issue('foreign_shared_in_callsite', producers[0])
    snapshots = assigned('snapshot')
    snapshot = snapshots[0].value if len(snapshots)==1 else None
    if not (isinstance(snapshot, ast.Subscript) and isinstance(snapshot.value, ast.Name) and snapshot.value.id == 'shared' and isinstance(snapshot.slice, ast.Constant) and snapshot.slice.value == 'input_snapshot'):
        issue('foreign_shared_in_callsite', caller)
    contexts = assigned('context')
    context = contexts[0].value if len(contexts)==1 else None
    if not (isinstance(context, ast.Call) and isinstance(context.func, ast.Name) and context.func.id=='make_n01_resolved_context' and len(context.args)==2 and not context.keywords and isinstance(context.args[0], ast.Name) and context.args[0].id=='retained' and isinstance(context.args[1], ast.Call) and isinstance(context.args[1].func, ast.Name) and context.args[1].func.id=='n01_presence' and len(context.args[1].args)==1 and not context.args[1].keywords and isinstance(context.args[1].args[0], ast.Name) and context.args[1].args[0].id=='resolution'):
        issue('foreign_shared_in_callsite', caller)
    calls=[]
    for idx, source, owner in nodes:
        for node in ast.walk(owner):
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id==entry_contract['core']:
                calls.append(node)
                if owner.name!=symbol or len(node.args)!=3 or node.keywords or [n.id if isinstance(n,ast.Name) else None for n in node.args]!=['snapshot','context','shared']:
                    problem('foreign_shared_in_callsite',owner.name,idx,source,node)
    if len(calls)!=1:
        issue('missing_direct_call',caller)
    for node in ast.walk(caller):
        if isinstance(node,ast.Subscript) and isinstance(node.value,ast.Name) and node.value.id=='shared' and isinstance(node.ctx,ast.Store):
            issue('foreign_shared_in_callsite',node)
        if isinstance(node,ast.Call) and isinstance(node.func,ast.Attribute) and isinstance(node.func.value,ast.Name) and node.func.value.id=='shared':
            issue('foreign_shared_in_callsite',node)
    return {'valid':not problems,'problems':problems}
